class Swiper {
  constructor(selector, options = {}) {
    this.el = typeof selector === "string" ? document.querySelector(selector) : selector;
    if (!this.el) return;

    this.options = options;
    this.wrapper = this.el.querySelector(".swiper-wrapper");
    if (!this.wrapper) return;

    this.original = [...this.wrapper.children];
    this.realCount = this.original.length;
    this.activeIndex = 0;
    this.dragging = false;
    this.startX = 0;
    this.currentX = 0;
    this.timer = null;
    this.transitioning = false;

    this.setup();
    this.bind();
    this.update(false);
    this.goTo(this.cloneCount, false);
    this.autoplay();
  }

  setup() {
    this.wrapper.innerHTML = "";
    const clonesNeeded = this.options.loop ? this.realCount : 0;
    this.cloneCount = clonesNeeded;

    if (this.options.loop && this.realCount) {
      this.original.slice(-clonesNeeded).forEach((slide) => {
        const clone = slide.cloneNode(true);
        clone.setAttribute("aria-hidden", "true");
        this.wrapper.appendChild(clone);
      });
    }

    this.original.forEach((slide) => this.wrapper.appendChild(slide));

    if (this.options.loop && this.realCount) {
      this.original.slice(0, clonesNeeded).forEach((slide) => {
        const clone = slide.cloneNode(true);
        clone.setAttribute("aria-hidden", "true");
        this.wrapper.appendChild(clone);
      });
    }

    this.slides = [...this.wrapper.children];
  }

  perView() {
    const width = window.innerWidth;
    const breakpoints = this.options.breakpoints || {};
    let per = this.options.slidesPerView || 1;

    Object.keys(breakpoints).map(Number).sort((a, b) => a - b).forEach((bp) => {
      if (width >= bp && breakpoints[bp].slidesPerView) {
        per = breakpoints[bp].slidesPerView;
      }
    });

    return Number(per) || 1;
  }

  gap() {
    const width = window.innerWidth;
    const breakpoints = this.options.breakpoints || {};
    let gap = this.options.spaceBetween || 0;

    Object.keys(breakpoints).map(Number).sort((a, b) => a - b).forEach((bp) => {
      if (width >= bp && breakpoints[bp].spaceBetween !== undefined) {
        gap = breakpoints[bp].spaceBetween;
      }
    });

    return Number(gap) || 0;
  }

  bind() {
    this.resize = () => {
      this.update(false);
      this.goTo(this.activeIndex, false);
    };
    window.addEventListener("resize", this.resize);

    this.wrapper.addEventListener("transitionend", () => this.fixLoopPosition());

    this.el.addEventListener("pointerdown", (event) => {
      if (!this.realCount) return;
      if (event.target.closest("button, a, input, textarea, select, .swiper-button-next, .swiper-button-prev")) return;
      this.dragging = true;
      this.startX = event.clientX;
      this.currentX = event.clientX;
      this.wrapper.style.transition = "none";
      this.el.setPointerCapture?.(event.pointerId);
    });

    this.el.addEventListener("pointermove", (event) => {
      if (!this.dragging) return;
      this.currentX = event.clientX;
      this.wrapper.style.transform = `translate3d(${this.offsetFor(this.activeIndex) + this.currentX - this.startX}px,0,0)`;
    });

    this.el.addEventListener("pointerup", () => this.releaseDrag());
    this.el.addEventListener("pointercancel", () => this.releaseDrag());

    this.navigationNext().forEach((button) => {
      button.addEventListener("click", () => this.next());
    });
    this.navigationPrev().forEach((button) => {
      button.addEventListener("click", () => this.prev());
    });
  }

  navigationNext() {
    return this.navigationElements("nextEl", ".swiper-button-next");
  }

  navigationPrev() {
    return this.navigationElements("prevEl", ".swiper-button-prev");
  }

  navigationElements(optionName, fallback) {
    const option = this.options.navigation?.[optionName];
    if (option instanceof Element) return [option];
    if (Array.isArray(option)) return option.filter(Boolean);
    if (typeof option === "string") return [...document.querySelectorAll(option)];
    return [...this.el.querySelectorAll(fallback)];
  }

  releaseDrag() {
    if (!this.dragging) return;
    this.dragging = false;
    this.wrapper.style.transition = "";
    const delta = this.currentX - this.startX;
    if (Math.abs(delta) > 45) {
      delta < 0 ? this.next() : this.prev();
    } else {
      this.goTo(this.activeIndex);
    }
  }

  update(animate = true) {
    this.per = this.perView();
    this.space = this.gap();
    this.step = 0;
    this.wrapper.style.gap = `${this.space}px`;
    this.wrapper.style.transition = animate ? "" : "none";
    this.slideW = (this.el.clientWidth - this.space * (this.per - 1)) / this.per;
    this.slides.forEach((slide) => {
      slide.style.width = `${this.slideW}px`;
      slide.style.marginRight = "0";
    });
    this.step = this.slideW + this.space;
  }

  offsetFor(index) {
    return -(index * this.step);
  }

  goTo(index, animate = true) {
    if (!this.slides.length) return;
    this.activeIndex = index;
    this.transitioning = animate;
    this.wrapper.style.transition = animate ? "" : "none";
    this.wrapper.style.transform = `translate3d(${this.offsetFor(this.activeIndex)}px,0,0)`;
    if (!animate) {
      requestAnimationFrame(() => {
        this.wrapper.style.transition = "";
      });
    }
  }

  next() {
    if (!this.realCount) return;
    this.goTo(this.activeIndex + 1);
  }

  prev() {
    if (!this.realCount) return;
    this.goTo(this.activeIndex - 1);
  }

  fixLoopPosition() {
    if (!this.options.loop || !this.realCount || !this.transitioning) return;
    this.transitioning = false;

    if (this.activeIndex >= this.cloneCount + this.realCount) {
      this.goTo(this.cloneCount, false);
    } else if (this.activeIndex < this.cloneCount) {
      this.goTo(this.cloneCount + this.realCount - 1, false);
    }
  }

  autoplay() {
    const delay = this.options.autoplay?.delay;
    if (!delay) return;
    clearInterval(this.timer);
    this.timer = setInterval(() => this.next(), delay);
    this.el.addEventListener("mouseenter", () => clearInterval(this.timer));
    this.el.addEventListener("mouseleave", () => this.autoplay(), { once: true });
  }
}
